// Follow-up gate for WhatsApp Business and SMS. Decides whether the assistant
// may send a follow-up to a customer. Keeps all state in memory; nothing is sent here.
//
// Rules, checked in this order:
//   opted-out              the customer's latest opt-in/opt-out keyword is a stop keyword
//   no-prior-inbound       the customer has never written to us
//   freeform-window-closed freeform text, and more than 24h since the customer's last message
//
// Templates skip the 24-hour window check. WhatsApp allows approved templates outside it.

const WINDOW_MS = 24 * 60 * 60 * 1000;

// Carrier opt-out and opt-in keywords (CTIA), matched against the whole message only.
const STOP_WORDS = new Set(["stop", "stopall", "unsubscribe", "cancel", "end", "quit"]);
const START_WORDS = new Set(["start", "yes", "unstop"]);

// Polite free-text stop requests. Anchored, so "stop by the store" is not a match.
const STOP_PHRASES = [
  /^(please )?(stop|quit) (texting|messaging|sending|contacting|bothering) me( please)?$/,
  /^(please )?(do not|don't|dont) (text|message|contact) me( anymore)?( please)?$/,
  /^(please )?(stop|unsubscribe|remove) me( please)?$/,
];

const states = new Map(); // userId -> { lastInboundMs, optEvent: { kind, atMs } | null }

function normalize(text) {
  return String(text)
    .normalize("NFKC")
    .toLowerCase()
    .replace(/[​-‍⁠﻿]/g, "") // zero-width characters
    .replace(/[’‘]/g, "'")
    .replace(/[^\p{L}\p{N}']+/gu, " ") // punctuation, emoji, symbols become spaces
    .trim()
    .replace(/\s+/g, " ");
}

// Returns "stop", "start", or null. A keyword counts only when it is the whole message.
function classify(text) {
  const words = normalize(text);
  if (words === "") return null;

  // Removing spaces and apostrophes lets "S.T.O.P" and "s t o p" match too.
  const compact = words.replace(/[\s']+/g, "");
  if (STOP_WORDS.has(compact)) return "stop";
  if (START_WORDS.has(compact)) return "start";

  if (STOP_PHRASES.some((re) => re.test(words))) return "stop";
  return null;
}

function validDate(value, name) {
  if (!(value instanceof Date) || Number.isNaN(value.getTime())) {
    throw new TypeError(`${name} must be a valid Date`);
  }
  return value.getTime();
}

export function onInbound(userId, text, at) {
  const atMs = validDate(at, "at");
  const state = states.get(userId) ?? { lastInboundMs: null, optEvent: null };

  state.lastInboundMs = state.lastInboundMs === null ? atMs : Math.max(state.lastInboundMs, atMs);

  // A late-arriving message does not overwrite a newer keyword.
  const kind = classify(text);
  if (kind !== null && (state.optEvent === null || atMs >= state.optEvent.atMs)) {
    state.optEvent = { kind, atMs };
  }

  states.set(userId, state);
}

export function check(userId, type, now) {
  if (type !== "freeform" && type !== "template") {
    throw new TypeError(`type must be "freeform" or "template", got ${String(type)}`);
  }
  const nowMs = validDate(now, "now");
  const state = states.get(userId);

  if (state?.optEvent?.kind === "stop") return { allowed: false, rule: "opted-out" };
  if (!state || state.lastInboundMs === null) return { allowed: false, rule: "no-prior-inbound" };

  if (type === "freeform") {
    const elapsed = nowMs - state.lastInboundMs;
    if (elapsed < 0 || elapsed >= WINDOW_MS) {
      return { allowed: false, rule: "freeform-window-closed" };
    }
  }

  return { allowed: true, rule: null };
}

import { test } from "node:test";
import assert from "node:assert/strict";
import { onInbound, check } from "./bot.mjs";

const H = 60 * 60 * 1000;
const t0 = new Date("2026-10-01T10:00:00Z");
let seq = 0;
const fresh = () => `user-${++seq}`;

test("never-written customer is blocked for both types", () => {
  const u = fresh();
  assert.deepEqual(check(u, "template", t0), { allowed: false, rule: "no-prior-inbound" });
  assert.deepEqual(check(u, "freeform", t0), { allowed: false, rule: "no-prior-inbound" });
});

test("freeform allowed inside 24h window, blocked at and after 24h", () => {
  const u = fresh();
  onInbound(u, "hi", t0);
  assert.deepEqual(check(u, "freeform", new Date(t0.getTime() + 23 * H)), { allowed: true, rule: null });
  assert.deepEqual(check(u, "freeform", new Date(t0.getTime() + 24 * H)), {
    allowed: false,
    rule: "freeform-window-closed",
  });
});

test("template allowed outside the window after any prior inbound", () => {
  const u = fresh();
  onInbound(u, "hello", t0);
  assert.deepEqual(check(u, "template", new Date(t0.getTime() + 100 * H)), { allowed: true, rule: null });
});

test("freeform check before the last inbound is blocked", () => {
  const u = fresh();
  onInbound(u, "hello", t0);
  assert.equal(check(u, "freeform", new Date(t0.getTime() - H)).rule, "freeform-window-closed");
});

test("stop keywords in any case, spacing, or punctuation opt out", () => {
  for (const text of ["STOP", "stop", " Stop! ", "stop.", "S.T.O.P", "s t o p", "STOPALL", "unsubscribe", "Cancel", "END", "quit", "stop 😊"]) {
    const u = fresh();
    onInbound(u, "hi", t0);
    onInbound(u, text, new Date(t0.getTime() + H));
    for (const type of ["template", "freeform"]) {
      assert.deepEqual(check(u, type, new Date(t0.getTime() + 2 * H)), { allowed: false, rule: "opted-out" }, `${text} / ${type}`);
    }
  }
});

test("polite free-text stop requests opt out", () => {
  for (const text of ["please stop texting me", "Stop messaging me.", "don't text me anymore", "Remove me please"]) {
    const u = fresh();
    onInbound(u, text, t0);
    assert.equal(check(u, "template", new Date(t0.getTime() + H)).rule, "opted-out", text);
  }
});

test("ordinary sentences containing keywords are not opt-outs", () => {
  for (const text of [
    "I will stop by the store later",
    "Can you cancel my order?",
    "Yes, my bill looks wrong",
    "the end of the month is fine",
    "do not stop the service please",
  ]) {
    const u = fresh();
    onInbound(u, text, t0);
    assert.deepEqual(check(u, "freeform", new Date(t0.getTime() + H)), { allowed: true, rule: null }, text);
  }
});

test("START, YES, UNSTOP restore consent after a stop", () => {
  for (const text of ["START", "yes", "Unstop!"]) {
    const u = fresh();
    onInbound(u, "hi", t0);
    onInbound(u, "STOP", new Date(t0.getTime() + H));
    onInbound(u, text, new Date(t0.getTime() + 2 * H));
    assert.deepEqual(check(u, "template", new Date(t0.getTime() + 3 * H)), { allowed: true, rule: null }, text);
  }
});

test("a stop is only undone by a later start, not by an older one", () => {
  const u = fresh();
  onInbound(u, "START", t0);
  onInbound(u, "STOP", new Date(t0.getTime() + H));
  onInbound(u, "hi again", new Date(t0.getTime() + 2 * H));
  assert.equal(check(u, "template", new Date(t0.getTime() + 3 * H)).rule, "opted-out");
});

test("late-arriving start does not override a newer stop", () => {
  const u = fresh();
  onInbound(u, "hi", t0);
  onInbound(u, "STOP", new Date(t0.getTime() + 2 * H));
  onInbound(u, "START", new Date(t0.getTime() + H));
  assert.equal(check(u, "template", new Date(t0.getTime() + 3 * H)).rule, "opted-out");
});

test("invalid inputs throw", () => {
  assert.throws(() => check(fresh(), "sms", t0), TypeError);
  assert.throws(() => check(fresh(), "freeform", new Date("nope")), TypeError);
  assert.throws(() => onInbound(fresh(), "hi", "2026-10-01"), TypeError);
});
